  /**
   * Cancels the underlying game event after the actions run.
   * @since 2.0.0
   * @registeredBy materione
   * @category flow
   */
  cancel(params?: CancelActionParams | boolean, options?: ActionOptions): ActionStep<"cancel">;
  /**
   * Makes the player say a chat message, or run a command as themselves.
   * @since 2.0.0
   * @registeredBy materione
   * @category player
   */
