  /**
   * Lets the player through once every given number of seconds, per player, and survives a restart. The variable must already be declared as a player number in a variables file of its pack.
   * @registeredBy materione
   */
  cooldownGate(params: CooldownGateRecipeParams): RecipeInstance<"cooldown_gate">;
  /**
   * Adds previous and next buttons that page a list layer. The list layer is placed in the GUI with type list; this recipe writes the buttons' rules.
   * @registeredBy materione
   */
