  /**
   * Takes a price from the player and gives them an item when they can pay. When they cannot, the message is shown and nothing changes.
   * @registeredBy materione
   */
  payToReceive(params: PayToReceiveRecipeParams): RecipeInstance<"pay_to_receive">;
  /**
   * Sends the player to another server when the button is clicked. The server must be known to the proxy, or the transfer packet must be configured.
   * @registeredBy materione
   */
  serverSelector(params: ServerSelectorRecipeParams): RecipeInstance<"server_selector">;
  /**
   * Flips a declared player boolean when the button is clicked, then tells the player the new state. The variable must already be declared in a variables file of its pack.
   * @registeredBy materione
   */
