  /**
   * Editor-only: the studio will not move or edit this layer.
   * @defaultValue false
   * @example true
   */
  locked?: boolean;
  /**
   * Raster layers only: 0 is transparent, 100 is opaque.
   * Range: 0 to 100 %.
   * @defaultValue 100
   * @example 100
   */
  opacity?: number;
  /** A condition (an expression, a predicate or a composite, as in a rule's require) that decides whether the layer is shown, checked on every render. The layer order is its priority, and the topmost visible layer of a slot wins. */
  visible_if?: JsonValue;
  /** Raster animation: {every: ticks, layers: [component-field patches]}. */
